#!/usr/bin/env bash
# Question 4: Name resolution broken. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q4_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q4_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q4_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: web
  namespace: ${Q4_NS}
spec:
  replicas: 1
  selector:
    matchLabels: { app: web }
  template:
    metadata:
      labels: { app: web }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
---
apiVersion: v1
kind: Service
metadata:
  name: web
  namespace: ${Q4_NS}
spec:
  selector: { app: web }
  ports: [{ port: 80 }]
EOF
kubectl -n "${Q4_NS}" delete pod client --ignore-not-found --wait=true >/dev/null
kubectl -n "${Q4_NS}" apply -f - <<< '{"apiVersion":"v1","kind":"Pod","metadata":{"name":"client"},"spec":{"containers":[{"name":"shell","image":"busybox:1.36","command":["sleep","infinity"]}]}}'
if ! kubectl -n "${Q4_NS}" wait --for=condition=Ready pod/client --timeout=180s; then
  kubectl -n "${Q4_NS}" describe pod/client >&2 || true
  exit 1
fi
kubectl -n "${Q4_NS}" rollout status deployment/web --timeout=180s

case "${Q4_FAULT}" in
  coredns-hosts-plugin)
    kubectl -n kube-system get configmap coredns -o jsonpath='{.data.Corefile}' > /tmp/cka-Corefile
    python3 -c 'import sys; from pathlib import Path; t=Path("/tmp/cka-Corefile").read_text(); n="kubernetes cluster.local"; i="hosts {\n        127.0.0.1 web." + sys.argv[1] + ".svc.cluster.local web.svc.cluster.local web.cluster.local web\n        fallthrough\n    }\n    "; Path("/tmp/cka-Corefile").write_text(t.replace(n, i+n, 1) if "hosts {" not in t else t)' "${Q4_NS}"
    grep -q "127.0.0.1 web.${Q4_NS}.svc.cluster.local" /tmp/cka-Corefile || { echo "could not inject hosts plugin" >&2; exit 1; }
    kubectl -n kube-system create configmap coredns --from-file=Corefile=/tmp/cka-Corefile -o yaml --dry-run=client | kubectl -n kube-system apply -f - >/dev/null
    kubectl -n kube-system delete pod -l k8s-app=kube-dns --wait=false >/dev/null
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

# The question only makes sense if the client really cannot resolve the name.
for _ in $(seq 1 60); do
  kubectl -n "${Q4_NS}" exec client -- wget -qO- -T 3 http://web 2>/dev/null | grep -q nginx || exit 0
  sleep 3
done
echo "the client still resolves web" >&2
exit 1
